// Writes apps/worker/src/store/migrations.gen.ts from packages/db/{directory,budget}-migrations/*.sql, so the
// Durable Objects get their migrations as plain strings (no bundler rules) and tests load exactly what production
// does. `--check` fails if the generated file is out of date (run by tools/ci/migration-check.mjs).
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

const OUT = 'apps/worker/src/store/migrations.gen.ts';
const read = (dir) =>
  readdirSync(dir)
    .filter((f) => f.endsWith('.sql'))
    .sort()
    .map((f) => ({ name: f, sql: readFileSync(`${dir}/${f}`, 'utf8') }));

const body =
  `// Generated by tools/db/gen-store-migrations.mjs from packages/db/{directory,budget}-migrations. Do not edit.\n` +
  `export interface StoreMigration {\n  name: string;\n  sql: string;\n}\n\n` +
  `export const DIRECTORY_MIGRATIONS: StoreMigration[] = ${JSON.stringify(read('packages/db/directory-migrations'), null, 2)};\n\n` +
  `export const BUDGET_MIGRATIONS: StoreMigration[] = ${JSON.stringify(read('packages/db/budget-migrations'), null, 2)};\n`;

if (process.argv.includes('--check')) {
  let cur = '';
  try {
    cur = readFileSync(OUT, 'utf8');
  } catch {
    // missing counts as out of date
  }
  if (cur !== body) {
    console.error(`${OUT} is out of date: run node tools/db/gen-store-migrations.mjs`);
    process.exit(1);
  }
  console.log('store migrations: generated file is current');
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${OUT}`);
}
